from __future__ import annotations

import threading
import time
import uuid
from dataclasses import dataclass, field
from typing import Any, Callable

from .audio import sweep_job_temps

ProgressCb = Callable[[dict[str, Any]], None]

# Keep finished jobs around for polling/SSE reconnects, then prune.
_JOB_TTL_S = 3600.0
_MAX_JOBS = 64
# Local GPU engine: serialize heavy pipelines by default to avoid VRAM thrash / OOM.
# Override with TRANSUB_MAX_CONCURRENT_JOBS (1–8) for CPU-only or multi-GPU hosts.
_MAX_CONCURRENT_JOBS = 1


def _default_max_concurrent_jobs() -> int:
    import os

    raw = str(os.environ.get("TRANSUB_MAX_CONCURRENT_JOBS") or "").strip()
    if not raw:
        return _MAX_CONCURRENT_JOBS
    try:
        return max(1, min(8, int(raw)))
    except (TypeError, ValueError):
        return _MAX_CONCURRENT_JOBS


def _normalize_perf_profile(raw: Any) -> str:
    """Return ``speed`` or ``quality`` (default)."""
    val = str(raw or "").strip().lower()
    if val in ("speed", "fast", "quick"):
        return "speed"
    return "quality"


def _target_file_suffix(request: dict[str, Any] | None) -> str:
    """Sidecar language tag for 成片 / dual target track (e.g. zh-cn, en).

    Empty string means same basename as the media file (`Movie.srt`).
    """
    import re

    req = request if isinstance(request, dict) else {}
    naming = str(
        req.get("targetSubtitleNaming")
        or req.get("target_subtitle_naming")
        or "lang"
    ).strip().lower()
    if naming in ("media", "same", "video", "bare"):
        return ""
    raw = (
        req.get("dualTargetSuffix")
        or req.get("dual_target_suffix")
        or req.get("targetSuffix")
        or req.get("target_suffix")
        or "zh-cn"
    )
    s = str(raw or "").strip().lower().replace("_", "-")
    if not s:
        return "zh-cn"
    # Legacy bare Chinese tags → zh-cn / zh-tw
    if s in ("zh", "chs", "cn"):
        return "zh-cn"
    if s in ("cht", "tw"):
        return "zh-tw"
    if s == "hk":
        return "zh-hk"
    if re.fullmatch(r"[a-z]{2,8}(?:-[a-z0-9]{2,8}){0,2}", s):
        return s
    return "zh-cn"


def _want_output_target(request: dict[str, Any] | None) -> bool:
    req = request if isinstance(request, dict) else {}
    if "outputWriteTarget" in req:
        return bool(req.get("outputWriteTarget"))
    if "output_write_target" in req:
        return bool(req.get("output_write_target"))
    return True


def _want_output_source(request: dict[str, Any] | None) -> bool:
    req = request if isinstance(request, dict) else {}
    if "outputWriteSource" in req:
        return bool(req.get("outputWriteSource"))
    if "output_write_source" in req:
        return bool(req.get("output_write_source"))
    return True


def _target_subtitle_basename(stem: str, tgt_tag: str, fmt: str) -> str:
    tag = str(tgt_tag or "").strip()
    if not tag:
        return f"{stem}.{fmt}"
    return f"{stem}.{tag}.{fmt}"


def _resolve_word_timestamps(include_words: bool, word_ts_raw: Any) -> bool:
    """DTW word alignment is expensive; on only for word/karaoke export or explicit True."""
    if include_words:
        return True
    if word_ts_raw is None:
        return False
    return bool(word_ts_raw)


class JobCancelled(RuntimeError):
    """Raised when a job cooperative-cancel is observed mid-pipeline."""

    def __init__(self, message: str = "cancelled") -> None:
        super().__init__(message)


@dataclass
class JobState:
    id: str
    status: str = "queued"
    request: dict[str, Any] = field(default_factory=dict)
    result: dict[str, Any] | None = None
    error: dict[str, Any] | None = None
    events: list[dict[str, Any]] = field(default_factory=list)
    cancelled: bool = False
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    _subprocs: list[Any] = field(default_factory=list)
    _subprocs_lock: threading.Lock = field(default_factory=threading.Lock)
    _events_lock: threading.Lock = field(default_factory=threading.Lock)

    def push(self, event: dict[str, Any]) -> None:
        payload = {"ts": time.time(), **event}
        with self._events_lock:
            self.events.append(payload)
        self.updated_at = time.time()

    def register_subprocess(self, proc: Any) -> None:
        with self._subprocs_lock:
            self._subprocs.append(proc)

    def kill_subprocesses(self, *, reason: str = "cancel") -> None:
        from .proc_util import kill_process_tree

        with self._subprocs_lock:
            procs = list(self._subprocs)
            self._subprocs.clear()
        for proc in procs:
            try:
                kill_process_tree(proc, reason=reason)
            except Exception:
                pass


class JobManager:
    def __init__(self, *, max_concurrent: int = _MAX_CONCURRENT_JOBS) -> None:
        self._jobs: dict[str, JobState] = {}
        self._lock = threading.Lock()
        self._run_sem = threading.Semaphore(max(1, int(max_concurrent)))

    def create(self, request: dict[str, Any], *, run_async: bool = True) -> JobState:
        job_id = uuid.uuid4().hex[:12]
        job = JobState(id=job_id, request=dict(request or {}))
        with self._lock:
            self._prune_locked()
            self._jobs[job_id] = job
        self._persist(job)
        if run_async:
            threading.Thread(target=self._run_job, args=(job_id,), daemon=True).start()
        else:
            self._run_job(job_id)
        return job

    def get(self, job_id: str) -> JobState | None:
        with self._lock:
            hit = self._jobs.get(job_id)
        if hit:
            return hit
        # Restart-friendly: terminal snapshot from disk (status only)
        try:
            from .job_store import load_job_snapshot

            snap = load_job_snapshot(job_id)
            if not snap:
                return None
            restored = JobState(
                id=job_id,
                status=str(snap.get("status") or "error"),
                request=dict(snap.get("request") or {}),
                error=snap.get("error") if isinstance(snap.get("error"), dict) else None,
            )
            restored.created_at = float(snap.get("createdAt") or restored.created_at)
            restored.updated_at = float(snap.get("updatedAt") or restored.updated_at)
            if isinstance(snap.get("resultSummary"), dict):
                restored.result = {
                    "task": snap["resultSummary"].get("task"),
                    "outputs": snap["resultSummary"].get("outputs"),
                    "mtModel": snap["resultSummary"].get("mtModel"),
                    "language": snap["resultSummary"].get("language"),
                    "persisted": True,
                }
            with self._lock:
                self._jobs[job_id] = restored
            return restored
        except Exception:
            return None

    def cancel(self, job_id: str) -> bool:
        job = self.get(job_id)
        if not job:
            return False
        already = bool(job.cancelled)
        job.cancelled = True
        # Kill Demucs / SenseVoice / other child processes immediately.
        try:
            job.kill_subprocesses(reason="job_cancel")
        except Exception:
            pass
        # Mark terminal ASAP so HTTP pollers (waitJob) can exit without waiting
        # for blocking FunASR.generate() to finish.
        if job.status in ("queued", "running"):
            job.status = "cancelled"
            job.error = {"code": "CANCELLED", "message": "cancelled"}
        if not already:
            job.push({"type": "progress", "stage": "cancel", "detail": "已请求取消"})
            job.push({"type": "error", "code": "CANCELLED", "message": "cancelled"})
        self._persist(job)
        return True

    def resume(
        self,
        job_id: str,
        *,
        run_async: bool = True,
        overrides: dict[str, Any] | None = None,
    ) -> JobState:
        """
        Create a new job that continues from a checkpoint of ``job_id``.

        Requires ``{job_id}.ckpt.json`` with at least ``asr_done`` (source cues).
        Optional ``overrides`` (e.g. fresh ``mtExternal`` URL) are merged after
        the checkpoint request so desktop adapters can rebind on resume.
        """
        from .checkpoint import build_resume_request, load_checkpoint

        ckpt = load_checkpoint(job_id)
        if not ckpt or not (ckpt.get("sourceCues") or []):
            raise FileNotFoundError(
                f"no resumable checkpoint for job {job_id} "
                "(need asr_done with source cues)"
            )
        req = build_resume_request(ckpt)
        # Prefer media path from original request; checkpoint already embeds it
        if not req.get("mediaPath"):
            snap_job = self.get(job_id)
            if snap_job and snap_job.request.get("mediaPath"):
                req["mediaPath"] = snap_job.request["mediaPath"]
        if isinstance(overrides, dict) and overrides:
            # Keep _checkpoint from build_resume_request; allow MT/output rebinding.
            ckpt_blob = req.get("_checkpoint")
            req.update({k: v for k, v in overrides.items() if k != "_checkpoint"})
            if ckpt_blob is not None:
                req["_checkpoint"] = ckpt_blob
        return self.create(req, run_async=run_async)

    def create_batch(
        self,
        requests: list[dict[str, Any]],
        *,
        batch_id: str | None = None,
        run_async: bool = True,
    ) -> tuple[str, list[JobState]]:
        """Enqueue many jobs; they share the process semaphore (serialized GPU)."""
        from .batch import build_batch_requests

        paths = [str(r.get("mediaPath") or "") for r in requests]
        bid, reqs = build_batch_requests(
            paths,
            template={},
            batch_id=batch_id,
            per_item=list(requests),
        )
        jobs: list[JobState] = []
        for req in reqs:
            jobs.append(self.create(req, run_async=run_async))
        return bid, jobs

    def get_batch_summary(self, batch_id: str) -> dict[str, Any]:
        from .batch import summarize_batch
        from .job_store import list_job_snapshots

        bid = str(batch_id or "").strip()
        if not bid:
            raise ValueError("batchId required")
        found: list[Any] = []
        seen: set[str] = set()
        with self._lock:
            for job in self._jobs.values():
                if str((job.request or {}).get("batchId") or "") == bid:
                    found.append(job)
                    seen.add(job.id)
        for row in list_job_snapshots(limit=200):
            jid = str(row.get("id") or "")
            if jid in seen:
                continue
            req = row.get("request") or {}
            if str(req.get("batchId") or "") == bid:
                found.append(row)
                seen.add(jid)
        if not found:
            raise FileNotFoundError(f"batch not found: {bid}")
        return summarize_batch(bid, found)

    def _persist(self, job: JobState) -> None:
        try:
            from .job_store import save_job_snapshot

            save_job_snapshot(job)
        except Exception:
            pass

    def _prune_locked(self) -> None:
        """Drop old terminal jobs; must hold self._lock."""
        from .job_store import delete_job_snapshot

        now = time.time()
        terminal = ("done", "error", "cancelled")
        stale = [
            jid
            for jid, job in self._jobs.items()
            if job.status in terminal and (now - float(job.updated_at or job.created_at)) > _JOB_TTL_S
        ]
        for jid in stale:
            self._jobs.pop(jid, None)
            try:
                delete_job_snapshot(jid)
            except Exception:
                pass
            try:
                from .checkpoint import delete_checkpoint

                delete_checkpoint(jid)
            except Exception:
                pass
        if len(self._jobs) <= _MAX_JOBS:
            return
        # Evict oldest terminal jobs first
        terminal_jobs = sorted(
            (
                (float(job.updated_at or job.created_at), jid)
                for jid, job in self._jobs.items()
                if job.status in terminal
            ),
            key=lambda x: x[0],
        )
        overflow = len(self._jobs) - _MAX_JOBS
        for _, jid in terminal_jobs[: max(0, overflow)]:
            self._jobs.pop(jid, None)
            try:
                delete_job_snapshot(jid)
            except Exception:
                pass
            try:
                from .checkpoint import delete_checkpoint

                delete_checkpoint(jid)
            except Exception:
                pass

    def _mark_cancelled(self, job: JobState, *, push_event: bool = False) -> None:
        job.status = "cancelled"
        job.error = {"code": "CANCELLED", "message": "cancelled"}
        if push_event:
            # Avoid duplicate CANCELLED when cancel() already pushed one.
            has_cancel_err = any(
                ev.get("type") == "error" and ev.get("code") == "CANCELLED" for ev in job.events
            )
            if not has_cancel_err:
                job.push({"type": "error", "code": "CANCELLED", "message": "cancelled"})
        self._persist(job)

    def _run_job(self, job_id: str) -> None:
        job = self.get(job_id)
        if not job:
            return
        if job.cancelled:
            self._mark_cancelled(job, push_event=True)
            return
        acquired = self._run_sem.acquire(blocking=True)
        try:
            if job.cancelled:
                self._mark_cancelled(job, push_event=True)
                return
            job.status = "running"
            self._persist(job)
            try:
                result = execute_job(job.request, job=job)
                if job.cancelled:
                    self._mark_cancelled(job, push_event=True)
                    return
                job.result = result
                job.status = "done"
                job.push({"type": "done", "ok": True, "result": result})
                self._persist(job)
            except JobCancelled:
                self._mark_cancelled(job, push_event=True)
            except Exception as err:
                # Progress / preprocess may raise bare RuntimeError("cancelled")
                if job.cancelled or _is_cancel_message(err):
                    self._mark_cancelled(job, push_event=True)
                    return
                import traceback
                import sys

                tb = traceback.format_exc()
                # QC 局部重转写等短窗常见「空结果」：只打一行，避免整段 Traceback 吓到用户
                msg = str(err or "")
                soft_empty = (
                    "未识别到有效字幕" in msg
                    or ("结果为空" in msg and "SenseVoice" in msg)
                )
                try:
                    if soft_empty:
                        print(f"[engine] ASR 空结果（已跳过）: {msg}", flush=True)
                    else:
                        print(tb, flush=True)
                except UnicodeEncodeError:
                    enc = getattr(sys.stdout, "encoding", None) or "utf-8"
                    line = (f"[engine] ASR 空结果（已跳过）: {msg}\n" if soft_empty else tb + "\n")
                    sys.stdout.buffer.write(line.encode(enc, errors="replace"))
                    sys.stdout.flush()
                code = getattr(err, "code", None)
                err_code = "ASR_EMPTY" if soft_empty else (str(code) if code else "JOB_FAILED")
                job.status = "error"
                job.error = {
                    "code": err_code,
                    "message": str(err),
                    "traceback": "" if soft_empty else tb,
                }
                job.push({"type": "error", "code": err_code, "message": str(err)})
                self._persist(job)
        finally:
            # Reclaim ASR / Demucs / ffmpeg scratch before releasing the run slot.
            try:
                sweep_job_temps()
            except Exception:
                pass
            if acquired:
                self._run_sem.release()


def _is_cancel_message(err: BaseException) -> bool:
    code = str(getattr(err, "code", "") or "")
    if code in ("MT_EXTERNAL_CANCELLED", "cancelled", "canceled"):
        return True
    msg = str(err or "").strip().lower()
    if "已取消" in str(err or ""):
        return True
    return (
        msg in ("cancelled", "canceled")
        or msg.endswith("cancelled")
        or msg.endswith("canceled")
        or "external mt cancelled" in msg
    )


def _emit(job: JobState | None, on_progress: ProgressCb | None, event: dict[str, Any]) -> None:
    if job and job.cancelled:
        raise JobCancelled()
    payload = {"type": "progress", **event}
    if job:
        job.push(payload)
    if on_progress:
        on_progress(payload)


def _guess_mt_language(language: str, cues: list[dict[str, Any]]) -> str:
    """Resolve auto language from ASR cue scripts when the job left language=auto."""
    lang = str(language or "auto").strip().lower()
    if lang and lang not in ("auto",):
        return lang
    sample = " ".join(str(c.get("text") or "") for c in (cues or [])[:12])
    if not sample.strip():
        return "en"
    ja = sum(1 for ch in sample if "\u3040" <= ch <= "\u30ff")
    ko = sum(1 for ch in sample if "\uac00" <= ch <= "\ud7af")
    zh = sum(1 for ch in sample if "\u4e00" <= ch <= "\u9fff")
    latin = sum(1 for ch in sample if ("a" <= ch.lower() <= "z"))
    # Hangul / kana are strong signals; Han alone often means Chinese ASR output.
    if ko >= 3 and ko >= ja:
        return "ko"
    if ja >= 3:
        return "ja"
    if zh >= 8 and ja < 2 and ko < 2 and latin < zh:
        return "zh"
    return "en"


def _is_chinese_lang(language: str) -> bool:
    """Han-script Chinese family (includes Yue/Cantonese)."""
    primary = str(language or "").strip().lower().replace("_", "-").split("-", 1)[0]
    return primary in ("zh", "cn", "yue", "chinese", "cantonese")


def _is_mandarin_chinese_lang(language: str) -> bool:
    """Mandarin Chinese only — Yue/Cantonese still needs MT → 普通话."""
    primary = str(language or "").strip().lower().replace("_", "-").split("-", 1)[0]
    return primary in ("zh", "cn", "chinese")


def _is_chinese_target_lang(language: str) -> bool:
    """Target is Mandarin Chinese (zh / zh-Hans / zh-Hant / cn)."""
    primary = str(language or "").strip().lower().replace("_", "-").split("-", 1)[0]
    return primary in ("zh", "cn", "chinese")


def _should_skip_mt_same_chinese(source_lang: str, target_lang: str) -> bool:
    """Skip MT only for Mandarin→Chinese. Yue→简/繁 must run 粤语书面→普通话."""
    return _is_mandarin_chinese_lang(source_lang) and _is_chinese_target_lang(target_lang)


def execute_job(
    request: dict[str, Any],
    *,
    job: JobState | None = None,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    from .job_pipeline import execute_job_pipeline

    return execute_job_pipeline(request, job=job, on_progress=on_progress)


JOBS = JobManager(max_concurrent=_default_max_concurrent_jobs())
